select month(signup_date) as signup_month, case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end as signup_cohort, count(case when country = 'UK' then 1 end) as uk_count from customers where signup_date >= '2025-10-01' and city in ('Tokyo', 'Bangkok') group by month(signup_date), case when year(signup_date) < 2024 then 'before_2024' when year(signup_date) = 2024 then '2024' else 'after_2024' end order by signup_month desc, signup_cohort desc limit 5;
